import { test, expect } from '@playwright/test';

const cases = [
  { query: 'apple', expected: 1 },
  { query: 'an', expected: 2 },
  { query: 'zzz', expected: 0 },
];

for (const { query, expected } of cases) {
  test(`search "${query}" shows ${expected} result(s)`, async ({ page }) => {
    await page.goto('/products');
    await page.getByLabel('Search products').fill(query);
    await expect(page.getByRole('row').filter({ has: page.getByRole('cell') })).toHaveCount(expected);
  });
}

test('unique data per worker', async ({ request }, testInfo) => {
  const title = `todo-w${testInfo.workerIndex}-${Date.now()}`;
  const res = await request.post('/api/todos', { data: { title } });
  expect(res.status()).toBe(201);
});
